package com.rikkeibank.customer.model; import jakarta.persistence.*; import java.io.Serializable; import java.time.LocalDateTime;
@Entity @Table(name="customers") public class Customer implements Serializable{private static final long serialVersionUID=1L; @Id @GeneratedValue(strategy=GenerationType.IDENTITY) private Long id; @Column(nullable=false,unique=true) private String identityUsername; @Column(nullable=false) private String fullName; @Column(nullable=false,unique=true) private String email; private String phone; @Column(nullable=false) private boolean active=true; @Column(nullable=false) private LocalDateTime createdAt=LocalDateTime.now();
public Long getId(){return id;}public void setId(Long v){id=v;}public String getIdentityUsername(){return identityUsername;}public void setIdentityUsername(String v){identityUsername=v;}public String getFullName(){return fullName;}public void setFullName(String v){fullName=v;}public String getEmail(){return email;}public void setEmail(String v){email=v;}public String getPhone(){return phone;}public void setPhone(String v){phone=v;}public boolean isActive(){return active;}public void setActive(boolean v){active=v;}public LocalDateTime getCreatedAt(){return createdAt;}public void setCreatedAt(LocalDateTime v){createdAt=v;}}
